/* Arcana Library service worker — generated by build.py from tools/sw-template.js.
   Stores the whole archive on the device so it can be read offline. */
const VERSION = "arcana-__VERSION__";
const FILES = __FILES__;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(VERSION);
    // Add files one by one so that a single failure does not stop the install.
    for (const f of FILES) {
      try { await cache.add(new Request(f, { cache: "reload" })); } catch (e) { /* skip */ }
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key !== VERSION) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener("message", async (event) => {
  if (event.data === "progress") {
    const cache = await caches.open(VERSION);
    const n = (await cache.keys()).length;
    event.source && event.source.postMessage({ type: "progress", cached: n, total: FILES.length });
  }
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    } catch (e) {
      if (req.mode === "navigate") return (await cache.match("offline.html")) || Response.error();
      return Response.error();
    }
  })());
});
